<?php
$month=trim($_GET['month']??date('Y-m'));
if(!preg_match('/^(\d{4})-(0[1-9]|1[0-2])$/',$month))$month=date('Y-m');
$first=new DateTimeImmutable($month.'-01');$last=$first->modify('last day of this month');
$rangeStart=$first->modify('-'.((int)$first->format('N')-1).' days');
$prev=$first->modify('-1 month')->format('Y-m');$next=$first->modify('+1 month')->format('Y-m');
$monthStart=$first->format('Y-m-01');$monthEnd=$last->format('Y-m-t');
$hq=$pdo->prepare('SELECT holiday_date,holiday_name FROM public_holidays WHERE holiday_date BETWEEN ? AND ? ORDER BY holiday_date');$hq->execute([$monthStart,$monthEnd]);
$holidayMap=[];foreach($hq->fetchAll() as $h)$holidayMap[$h['holiday_date']]=$h['holiday_name'];
$leaveMap=[];
if($role==='employee'&&$self){$lq=$pdo->prepare("SELECT start_date,end_date FROM leaves WHERE employee_id=? AND status='Approved' AND start_date<=? AND end_date>=?");$lq->execute([(int)$self['id'],$monthEnd,$monthStart]);foreach($lq->fetchAll() as $leave){$from=max($monthStart,$leave['start_date']);$to=min($monthEnd,$leave['end_date']);for($day=new DateTimeImmutable($from);$day<=new DateTimeImmutable($to);$day=$day->modify('+1 day')){$key=$day->format('Y-m-d');if($day->format('w')!=='0'&&!isset($holidayMap[$key]))$leaveMap[$key]=true;}}}
?>
<section class="panel calendar-panel admin-calendar-panel">
  <div class="panel-head calendar-panel-head"><div><span class="eyebrow"><?=$role==='admin'?'WORKSPACE CALENDAR':'EMPLOYEE CALENDAR'?></span><h2><?=$role==='employee'?'Your calendar':'Public holiday calendar'?></h2><p><?=$role==='employee'?'Public holidays and Sundays stay separate from your leave. Approved leave appears as “On leave”.':'Manage public holidays and review the month at a glance.'?></p></div><div class="calendar-nav"><a class="button secondary" href="?month=<?=e($prev)?>" aria-label="Previous month">←</a><b><?=e($first->format('F Y'))?></b><a class="button secondary" href="?month=<?=e($next)?>" aria-label="Next month">→</a></div></div>
  <?php if($role==='admin'):?><form method="post" class="holiday-admin-form"><?=csrf_field()?><input type="hidden" name="action" value="holiday_save"><label>Holiday name<input name="holiday_name" maxlength="160" required placeholder="e.g. Diwali"></label><label>Date<input type="date" name="holiday_date" required></label><button class="button primary" type="submit"><?=ems_icon('plus')?>Add holiday</button></form><?php endif;?>
  <?php if($role==='employee'):?><div class="calendar-legend"><span><i class="holiday-key"></i>Public holiday</span><span><i class="leave-key"></i>On leave</span><span><i class="off-key"></i>Weekly off</span></div><?php else:?><div class="calendar-legend admin-calendar-legend"><span><i class="holiday-key"></i>Public holiday</span><span><i class="off-key"></i>Sunday · weekly off</span><span class="holiday-count"><b><?=count($holidayMap)?></b> holidays this month</span></div><?php endif;?>
  <div class="calendar-weekdays"><?php foreach(['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'] as $weekday):?><span><?=e(substr($weekday,0,3))?></span><?php endforeach;?></div>
  <div class="calendar-grid"><?php for($i=0;$i<42;$i++):$d=$rangeStart->modify('+'.$i.' days');$key=$d->format('Y-m-d');$outside=$d->format('m')!==$first->format('m');$isHoliday=isset($holidayMap[$key]);$isLeave=isset($leaveMap[$key]);$isSunday=$d->format('w')==='0';?><article class="calendar-day <?=$outside?'outside':''?> <?=$isSunday?'sunday':''?> <?=$isHoliday?'holiday':''?> <?=$isLeave?'on-leave':''?>" data-date="<?=e($key)?>"><b><?=e($d->format('j'))?></b><?php if($isHoliday):?><span><?=e($holidayMap[$key])?></span><?php elseif($isLeave):?><span>On leave</span><?php elseif($isSunday):?><small>Weekly off</small><?php endif;?></article><?php endfor;?></div>
  <?php if($role==='admin'):?><div class="holiday-list"><div class="holiday-list-heading"><div><h3>Holidays this month</h3><p><?=count($holidayMap)?> scheduled</p></div></div><?php if(!$holidayMap):?><div class="holiday-empty"><span><?=ems_icon('calendar')?></span><b>No holidays this month</b><small>Use the form above to add a date.</small></div><?php else:?><div class="holiday-card-grid"><?php foreach($holidayMap as $date=>$name):?><article class="holiday-admin-card"><div class="holiday-date-tile"><small><?=e(date('D',strtotime($date)))?></small><b><?=e(date('j',strtotime($date)))?></b></div><div class="holiday-card-copy"><b><?=e($name)?></b><small><?=e(date('F j, Y',strtotime($date)))?></small></div><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="holiday_delete"><input type="hidden" name="holiday_date" value="<?=e($date)?>"><button class="holiday-remove" aria-label="Remove <?=e($name)?>" title="Remove holiday"><?=ems_icon('close')?></button></form></article><?php endforeach;?></div><?php endif;?></div><?php endif;?>
</section>
